-- Migration 0015: motion control plane registry and immutable release seeds.
-- Additive only. Rollback is a forward fix: disable channel pointers and preserve audit rows.

CREATE TABLE IF NOT EXISTS motion_activities (id TEXT PRIMARY KEY, display_name TEXT NOT NULL, category TEXT NOT NULL, proof_label TEXT NOT NULL, measurement_type TEXT NOT NULL CHECK (measurement_type IN ('repetitions', 'duration', 'distance')), metric TEXT NOT NULL CHECK (metric IN ('reps', 'seconds')), suggested_targets_json TEXT NOT NULL, supported_formats_json TEXT NOT NULL, icon_key TEXT NOT NULL, sort_priority INTEGER NOT NULL DEFAULT 100, featured INTEGER NOT NULL DEFAULT 0, availability TEXT NOT NULL DEFAULT 'supported', metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_motion_activities_availability ON motion_activities(availability, sort_priority);

CREATE TABLE IF NOT EXISTS verifier_releases (id TEXT PRIMARY KEY, activity_id TEXT NOT NULL, semver TEXT NOT NULL, change_class TEXT NOT NULL, engine_type TEXT NOT NULL, spec_schema_version INTEGER NOT NULL, spec_json TEXT NOT NULL, object_key TEXT, checksum TEXT NOT NULL UNIQUE, required_capabilities_json TEXT NOT NULL, minimum_app_build TEXT NOT NULL, compatibility_group TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', release_notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, published_at TEXT, parent_release_id TEXT, FOREIGN KEY(activity_id) REFERENCES motion_activities(id), FOREIGN KEY(parent_release_id) REFERENCES verifier_releases(id));
CREATE INDEX IF NOT EXISTS idx_verifier_releases_activity_status ON verifier_releases(activity_id, status, created_at DESC);

CREATE TABLE IF NOT EXISTS activity_channel_releases (activity_id TEXT NOT NULL, channel TEXT NOT NULL CHECK (channel IN ('internal', 'beta', 'stable')), release_id TEXT NOT NULL, rollout_percent INTEGER NOT NULL DEFAULT 0 CHECK (rollout_percent BETWEEN 0 AND 100), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (activity_id, channel), FOREIGN KEY(activity_id) REFERENCES motion_activities(id), FOREIGN KEY(release_id) REFERENCES verifier_releases(id));

CREATE TABLE IF NOT EXISTS race_verifier_assignments (race_id TEXT PRIMARY KEY, activity_id TEXT NOT NULL, release_id TEXT NOT NULL, release_checksum TEXT NOT NULL, assignment_policy TEXT NOT NULL CHECK (assignment_policy IN ('pinned', 'follow_compatible_patch')), compatibility_group TEXT NOT NULL, assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, assignment_reason TEXT NOT NULL, FOREIGN KEY(race_id) REFERENCES races(id), FOREIGN KEY(activity_id) REFERENCES motion_activities(id), FOREIGN KEY(release_id) REFERENCES verifier_releases(id));
CREATE INDEX IF NOT EXISTS idx_race_verifier_assignments_activity ON race_verifier_assignments(activity_id, release_id);

CREATE TABLE IF NOT EXISTS verification_sessions (id TEXT PRIMARY KEY, race_id TEXT NOT NULL, user_id TEXT NOT NULL, activity_id TEXT NOT NULL, release_id TEXT NOT NULL, release_checksum TEXT NOT NULL, spec_schema_version INTEGER NOT NULL, engine_type TEXT NOT NULL, app_version TEXT NOT NULL, app_build TEXT NOT NULL, runtime_capabilities_json TEXT NOT NULL, status TEXT NOT NULL, result_value INTEGER, confidence REAL, failure_reason TEXT, started_at TEXT, completed_at TEXT, motion_session_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(race_id) REFERENCES races(id), FOREIGN KEY(activity_id) REFERENCES motion_activities(id), FOREIGN KEY(release_id) REFERENCES verifier_releases(id));
CREATE INDEX IF NOT EXISTS idx_verification_sessions_race ON verification_sessions(race_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_verification_sessions_user ON verification_sessions(user_id, created_at DESC);

CREATE TABLE IF NOT EXISTS verifier_evaluation_runs (id TEXT PRIMARY KEY, release_id TEXT NOT NULL, dataset_snapshot_id TEXT NOT NULL, status TEXT NOT NULL, report_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT, FOREIGN KEY(release_id) REFERENCES verifier_releases(id));

ALTER TABLE races ADD COLUMN verifier_release_id TEXT;
ALTER TABLE motion_sessions ADD COLUMN verifier_release_id TEXT;
ALTER TABLE motion_sessions ADD COLUMN verifier_release_checksum TEXT;
ALTER TABLE motion_sessions ADD COLUMN engine_type TEXT;
ALTER TABLE motion_sessions ADD COLUMN spec_schema_version INTEGER;
ALTER TABLE motion_sessions ADD COLUMN assignment_policy TEXT;

