INSERT OR IGNORE INTO race_verifier_assignments (race_id, activity_id, release_id, release_checksum, assignment_policy, compatibility_group, assignment_reason) SELECT r.id, r.activity_id, vr.id, vr.checksum, 'follow_compatible_patch', vr.compatibility_group, 'manual_migration' FROM races r JOIN motion_activities ma ON ma.id = r.activity_id JOIN activity_channel_releases ac ON ac.activity_id = ma.id AND ac.channel = 'stable' JOIN verifier_releases vr ON vr.id = ac.release_id WHERE r.activity_id IS NOT NULL AND COALESCE(r.verifier_type, 'preset_pose') <> 'custom_pose_sequence';
UPDATE races SET verifier_release_id = (SELECT a.release_id FROM race_verifier_assignments a WHERE a.race_id = races.id) WHERE verifier_release_id IS NULL AND id IN (SELECT race_id FROM race_verifier_assignments);
